package aliasmapbench

import (
	gts "github.com/odvcencio/gotreesitter"
	"github.com/odvcencio/gotreesitter/grammars"
	"github.com/odvcencio/gotreesitter/internal/benchfixtures"
	"os"
	"testing"
)

func fixture(b *testing.B) (*gts.Language, []byte) {
	b.Helper()
	name := os.Getenv("ALIAS_BENCH_LANGUAGE")
	for _, entry := range grammars.AllLanguages() {
		if entry.Name == name {
			source, err := os.ReadFile("../../internal/benchfixtures/testdata/real/" + name)
			if err != nil {
				b.Fatal(err)
			}
			return entry.Language(), source
		}
	}
	b.Fatalf("unknown grammar %q", name)
	return nil, nil
}

func BenchmarkFull(b *testing.B) {
	lang, source := fixture(b)
	parser := gts.NewParser(lang)
	tree, err := parser.Parse(source)
	if err != nil {
		b.Fatal(err)
	}
	tree.Release()
	b.ReportAllocs()
	b.SetBytes(int64(len(source)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		tree, err := parser.Parse(source)
		if err != nil {
			b.Fatal(err)
		}
		tree.Release()
	}
}

func BenchmarkEdit(b *testing.B) {
	lang, source := fixture(b)
	parser := gts.NewParser(lang)
	step := benchfixtures.EditingSession(source)[0]
	b.ReportAllocs()
	b.SetBytes(int64(len(step.Source)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		b.StopTimer()
		old, err := parser.Parse(source)
		if err != nil {
			b.Fatal(err)
		}
		b.StartTimer()
		old.Edit(step.Edit)
		tree, err := parser.ParseIncremental(step.Source, old)
		if err != nil {
			b.Fatal(err)
		}
		b.StopTimer()
		tree.Release()
		old.Release()
		b.StartTimer()
	}
}

func BenchmarkNoEdit(b *testing.B) {
	lang, source := fixture(b)
	parser := gts.NewParser(lang)
	tree, err := parser.Parse(source)
	if err != nil {
		b.Fatal(err)
	}
	defer tree.Release()
	b.ReportAllocs()
	b.SetBytes(int64(len(source)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		next, err := parser.ParseIncremental(source, tree)
		if err != nil {
			b.Fatal(err)
		}
		next.Release()
	}
}

reproduction_helpers.c_hidden_subtree_census_source:
#include <tree_sitter/api.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include "tree.h"

static uint64_t counts[65536];
static uint64_t unary[65536];
static void census(Subtree subtree) {
  TSSymbol symbol = ts_subtree_symbol(subtree);
  uint32_t children = ts_subtree_child_count(subtree);
  counts[symbol]++;
  if (children == 1) unary[symbol]++;
  for (uint32_t i = 0; i < children; i++) census(ts_subtree_children(subtree)[i]);
}

int main(int argc, char **argv) {
  if (argc != 4) return 2;
  void *handle = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
  if (!handle) { fprintf(stderr, "%s\n", dlerror()); return 1; }
  const TSLanguage *(*language)(void) = dlsym(handle, argv[2]);
  if (!language) return 1;
  FILE *source = fopen(argv[3], "rb");
  if (!source) return 1;
  fseek(source, 0, SEEK_END); long size = ftell(source); rewind(source);
  char *text = malloc(size); if (!text) return 1;
  if (fread(text, 1, size, source) != (size_t)size) return 1;
  fclose(source);
  TSParser *parser = ts_parser_new();
  if (!ts_parser_set_language(parser, language())) return 1;
  TSTree *tree = ts_parser_parse_string(parser, NULL, text, size);
  if (!tree) return 1;
  census(tree->root);
  for (uint32_t symbol = 0; symbol < ts_language_symbol_count(language()); symbol++) {
    if (counts[symbol]) printf("%u\t%llu\t%llu\t%s\n", symbol,
      (unsigned long long)counts[symbol], (unsigned long long)unary[symbol],
      ts_language_symbol_name(language(), symbol));
  }
  ts_tree_delete(tree); ts_parser_delete(parser); free(text); dlclose(handle);
  return 0;
}

reproduction_helpers.root_invariant_source:
package aliasmapbench

import (
	"fmt"
	gts "github.com/odvcencio/gotreesitter"
	"github.com/odvcencio/gotreesitter/grammars"
	"os"
	"testing"
)

func TestInvariant(b *testing.T) {
	// Each process checks one grammar, on the same pinned counter fixture.
	name := fixtureLanguage()
	entry, source := invariantFixture(b, name)
	for _, compact := range []bool{false, true} {
		b.Run(fmt.Sprintf("compact=%t", compact), func(t *testing.T) {
			parser := gts.NewParser(entry.Language())
			parser.SetAdmissionCandidateRoute(compact)
			tree, err := parser.Parse(source)
			if err != nil {
				t.Fatal(err)
			}
			defer tree.Release()
			root := tree.RootNode()
			if root == nil {
				t.Fatal("nil root")
			}
			if root.IsError() && !root.HasError() {
				t.Fatal("ERROR root lacks HasError")
			}
			if (root.StartByte() != 0 || root.EndByte() != uint32(len(source))) && (tree.ParseStopReason() == gts.ParseStopAccepted || tree.ParseStopReason() == gts.ParseStopNone) {
				t.Errorf("root %d..%d does not cover %d bytes with stop %s", root.StartByte(), root.EndByte(), len(source), tree.ParseStopReason())
			}
			allocations := testing.AllocsPerRun(10, func() {
				next, err := parser.ParseIncremental(source, tree)
				if err != nil {
					panic(err)
				}
				next.Release()
			})
			t.Logf("no-edit allocations = %.1f", allocations)
			if allocations != 0 {
				t.Fatalf("no-edit allocations = %.1f, want zero", allocations)
			}
		})
	}
}

func fixtureLanguage() string { return os.Getenv("ALIAS_BENCH_LANGUAGE") }
func invariantFixture(t *testing.T, name string) (grammars.LangEntry, []byte) {
	t.Helper()
	for _, entry := range grammars.AllLanguages() {
		if entry.Name == name {
			source, err := os.ReadFile("../../internal/benchfixtures/testdata/real/" + name)
			if err != nil {
				t.Fatal(err)
			}
			return entry, source
		}
	}
	t.Fatalf("unknown grammar %q", name)
	return grammars.LangEntry{}, nil
}

parser_only_resources.helper_source:
package main

import (
	"encoding/json"
	"fmt"
	gts "github.com/odvcencio/gotreesitter"
	"github.com/odvcencio/gotreesitter/grammars"
	"os"
	"runtime"
)

func main() {
	if len(os.Args) != 4 {
		panic("expected grammar, source path, route")
	}
	name, path, route := os.Args[1], os.Args[2], os.Args[3]
	source, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	for _, entry := range grammars.AllLanguages() {
		if entry.Name != name {
			continue
		}
		parser := gts.NewParser(entry.Language())
		parser.SetAdmissionCandidateRoute(route == "compact")
		tree, err := parser.Parse(source)
		if err != nil {
			panic(err)
		}
		root := tree.RootNode()
		if root == nil {
			panic("nil root")
		}
		var memory runtime.MemStats
		runtime.ReadMemStats(&memory)
		result := map[string]interface{}{"grammar": name, "route": route, "bytes": len(source), "root_start": root.StartByte(), "root_end": root.EndByte(), "has_error": root.HasError(), "stop_reason": fmt.Sprintf("%s", tree.ParseStopReason()), "heap_alloc_bytes": memory.HeapAlloc, "heap_sys_bytes": memory.HeapSys}
		if err := json.NewEncoder(os.Stdout).Encode(result); err != nil {
			panic(err)
		}
		tree.Release()
		return
	}
	panic(fmt.Sprintf("unknown grammar %q", name))
}
